async function refreshTok(){try{const a=JSON.parse(sg('khutwa_auth')),r=await fetch(CF.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:HD(0,{'Content-Type':'application/json'}),body:JSON.stringify({refresh_token:a.refresh_token})});if(!r.ok)return false;const j=await r.json();ss('khutwa_auth',JSON.stringify({access_token:j.access_token,refresh_token:j.refresh_token}));return true}catch(e){return false}}
